import re

_FORMATO = re.compile(r"\s*([0-9]{1,2}):([0-9]{2})\s*-\s*([0-9]{1,2}):([0-9]{2})\s*")
_DIA = 24 * 60


def _ler(texto):
    m = _FORMATO.fullmatch(texto) if isinstance(texto, str) else None
    if not m:
        raise ValueError(f"horário inválido: {texto!r}")
    h1, m1, h2, m2 = map(int, m.groups())
    if h1 > 23 or h2 > 23 or m1 > 59 or m2 > 59:
        raise ValueError(f"horário inválido: {texto!r}")
    inicio, fim = h1 * 60 + m1, h2 * 60 + m2
    if inicio == fim:
        raise ValueError(f"horário inválido (início igual ao fim): {texto!r}")
    if fim < inicio:  # passa da meia-noite: termina no dia seguinte
        fim += _DIA
    return inicio, fim


def _escrever(minutos):
    minutos %= _DIA
    return f"{minutos // 60:02d}:{minutos % 60:02d}"


def juntar(horarios):
    juntados = []
    for inicio, fim in sorted(_ler(t) for t in horarios):
        if juntados and inicio <= juntados[-1][1]:
            juntados[-1][1] = max(juntados[-1][1], fim)
        else:
            juntados.append([inicio, fim])
    return [f"{_escrever(i)}-{_escrever(f)}" for i, f in juntados]

